{
  "name": "气体选择系统",
  "name_en": "Gas Selection System",
  "manufacturer": "",
  "description": "一种用于管理多路气体、真空歧管和多个腔室阀门的气体处理装置。它可对腔室和歧管执行抽真空、氮气吹扫，并按设定压力与比例充入 Ar、He、N2 等气体，常用于同步辐射束线中气体电离室或类似检测腔体的准备与运行。",
  "description_en": "A gas handling and selection device with multiple gas lines, a vacuum manifold, and chamber valves. It can evacuate chambers and the manifold, purge with nitrogen, and fill chambers with gases such as Ar, He, and N2 at defined pressures and proportions. It is commonly used to prepare gas-filled ionization chambers or similar detector chambers on synchrotron beamlines.",
  "tag_hints": [
    "gas selection system",
    "gas manifold",
    "vacuum and purge",
    "valve control",
    "chamber filling",
    "gas mixing",
    "ionization chambers",
    "synchrotron beamline instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-close_all_chambers",
      "description": "关闭所有腔室阀门。",
      "description_en": "Close all chamber valves."
    },
    {
      "action_name": "auto-close_all_valves",
      "description": "关闭所有阀门。",
      "description_en": "Close all valves."
    },
    {
      "action_name": "auto-close_valve",
      "description": "关闭指定阀门。",
      "description_en": "Close a specified valve."
    },
    {
      "action_name": "auto-do_vacuum_all_chambers",
      "description": "对所有腔室执行抽真空流程。",
      "description_en": "Run the vacuum procedure for all chambers."
    },
    {
      "action_name": "auto-do_vacuum_manifold",
      "description": "对气体歧管执行抽真空流程。",
      "description_en": "Run the vacuum procedure for the gas manifold."
    },
    {
      "action_name": "auto-fill_all_chambers",
      "description": "按配置的气体方案为所有腔室充气。",
      "description_en": "Fill all chambers using the configured gas scheme."
    },
    {
      "action_name": "auto-fill_all_chambers_with_a_gas",
      "description": "用指定气体为所有腔室充气。",
      "description_en": "Fill all chambers with a specified gas."
    },
    {
      "action_name": "auto-open_all_chambers",
      "description": "打开所有腔室阀门。",
      "description_en": "Open all chamber valves."
    },
    {
      "action_name": "auto-open_all_valves",
      "description": "打开所有阀门。",
      "description_en": "Open all valves."
    },
    {
      "action_name": "auto-open_valve",
      "description": "打开指定阀门。",
      "description_en": "Open a specified valve."
    },
    {
      "action_name": "auto-purge_all_chambers",
      "description": "对所有腔室执行吹扫流程。",
      "description_en": "Run the purge procedure for all chambers."
    },
    {
      "action_name": "auto-set_edge",
      "description": "设置吸收边。",
      "description_en": "Set the absorption edge."
    },
    {
      "action_name": "auto-set_element",
      "description": "设置目标元素。",
      "description_en": "Set the target element."
    },
    {
      "action_name": "auto-set_extratime_manifold",
      "description": "设置歧管充气额外等待时间。",
      "description_en": "Set the extra wait time for manifold filling."
    },
    {
      "action_name": "auto-set_extratime_manifold_vacuum",
      "description": "设置歧管抽真空额外等待时间。",
      "description_en": "Set the extra wait time for manifold vacuum."
    },
    {
      "action_name": "auto-set_gas_proportions",
      "description": "设置气体比例。",
      "description_en": "Set the gas proportions."
    },
    {
      "action_name": "auto-set_pressure_vacuum",
      "description": "设置目标真空压力。",
      "description_en": "Set the target vacuum pressure."
    },
    {
      "action_name": "auto-set_pressure_work",
      "description": "设置目标工作压力。",
      "description_en": "Set the target working pressure."
    },
    {
      "action_name": "auto-start",
      "description": "启动完整的吹扫和充气流程。",
      "description_en": "Start the full purge-and-fill procedure."
    },
    {
      "action_name": "auto-get_element",
      "description": "获取目标元素。",
      "description_en": "Get the target element."
    },
    {
      "action_name": "auto-get_edge",
      "description": "获取吸收边。",
      "description_en": "Get the absorption edge."
    },
    {
      "action_name": "auto-get_pressure_vacuum",
      "description": "获取目标真空压力。",
      "description_en": "Get the target vacuum pressure."
    },
    {
      "action_name": "auto-get_pressure_work",
      "description": "获取目标工作压力。",
      "description_en": "Get the target working pressure."
    },
    {
      "action_name": "auto-get_extratime_manifold",
      "description": "获取歧管充气额外等待时间。",
      "description_en": "Get the extra wait time for manifold filling."
    },
    {
      "action_name": "auto-get_extratime_manifold_vacuum",
      "description": "获取歧管抽真空额外等待时间。",
      "description_en": "Get the extra wait time for manifold vacuum."
    },
    {
      "action_name": "auto-get_gas_proportions",
      "description": "获取气体比例。",
      "description_en": "Get the gas proportions."
    }
  ]
}

